ST.xhtml:p:
IF g_bSustainEnable THEN
  FBSustainPower();
  FBNewSupport();
  FBSustainJogControl();
  FBSustainFollowControl();
  FBSustainAct();
  FBSustainInchControl();
  FBSustainAbsolute();
  FBSustainHome();
  FBSustainVelAdd();
  bSustainAxis1ErrorAlarm :=  Axis_Sustain1.NCTOPLC.POWERPOSWARN OR Axis_Sustain1.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain1.NCTOPLC.ERRORCODE <>0;

  bSustainAxis2ErrorAlarm :=  Axis_Sustain2.NCTOPLC.POWERPOSWARN OR Axis_Sustain2.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain2.NCTOPLC.ERRORCODE <>0;

  bSustainAxis3ErrorAlarm :=  Axis_Sustain3.NCTOPLC.POWERPOSWARN OR Axis_Sustain3.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain3.NCTOPLC.ERRORCODE <>0;

  bSustainAxis4ErrorAlarm :=  Axis_Sustain7.NCTOPLC.POWERPOSWARN OR Axis_Sustain7.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain7.NCTOPLC.ERRORCODE <>0;

  bSustainAxis5ErrorAlarm :=  Axis_Sustain8.NCTOPLC.POWERPOSWARN OR Axis_Sustain8.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain8.NCTOPLC.ERRORCODE <>0;

  bSustainAxis6ErrorAlarm :=  Axis_Sustain9.NCTOPLC.POWERPOSWARN OR Axis_Sustain9.NCTOPLC.POWERNEGWARN 
     OR Axis_Sustain9.NCTOPLC.ERRORCODE <>0;




  IF bSustainAxis1ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain1Reset.Execute := TRUE;
  ELSE
    g_Sustain1Reset.Execute := FALSE;   
  END_IF;
  IF bSustainAxis2ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain2Reset.Execute := TRUE;
  ELSE
    g_Sustain2Reset.Execute := FALSE;   
  END_IF;
  IF bSustainAxis3ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain3Reset.Execute := TRUE;
  ELSE
    g_Sustain3Reset.Execute := FALSE;   
  END_IF;
  IF bSustainAxis4ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain7Reset.Execute := TRUE;
  ELSE
    g_Sustain7Reset.Execute := FALSE;   
  END_IF;
  IF bSustainAxis5ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain8Reset.Execute := TRUE;
  ELSE
    g_Sustain8Reset.Execute := FALSE;   
  END_IF;
  IF bSustainAxis6ErrorAlarm AND g_bPlcResetBuffer THEN
    g_Sustain9Reset.Execute := TRUE;
  ELSE
    g_Sustain9Reset.Execute := FALSE;   
  END_IF;

END_IF;
FBSustainFollowControlExt();
FBSustainDown();
